const challenges={config:{title:'민감한 설정 정보 노출',flag:'FLAG{debug_left_open}',reward:50000,lesson:'개발용 설정은 운영 환경에서 비활성화하고, 비밀 값은 서버에서만 관리해야 합니다.'},idor:{title:'다른 사용자의 메모 열람',flag:'FLAG{check_the_owner}',reward:100000,lesson:'메모를 조회할 때마다 서버에서 현재 사용자와 메모 소유자가 같은지 확인해야 합니다.'},role:{title:'관리자 권한 검증 누락',flag:'FLAG{never_trust_the_client}',reward:200000,lesson:'브라우저가 보낸 역할을 신뢰하지 말고 서버의 인증된 세션에서 권한을 확인해야 합니다.'}};
let reports=[];try{const saved=JSON.parse(localStorage.getItem('bounty-lab-v1')||'[]');if(Array.isArray(saved)){const seen=new Set();reports=saved.filter(r=>r&&challenges[r.type]&&typeof r.date==='string'&&!seen.has(r.type)&&seen.add(r.type));}}catch{}
const $=id=>document.getElementById(id);const money=value=>value.toLocaleString('ko-KR');
function update(){ $('balance').textContent=money(reports.reduce((sum,r)=>sum+challenges[r.type].reward,0));$('count').textContent=reports.length;$('progress').style.width=reports.length/3*100+'%';$('history-count').textContent=reports.length;$('progress-message').textContent=reports.length===3?'모든 취약점을 찾았어요. 멋진 첫 실습입니다!':reports.length?'좋은 발견이에요. 남은 취약점도 찾아보세요.':'아직 발견하지 못한 버그가 기다리고 있어요.';document.querySelectorAll('[data-done]').forEach(el=>{el.textContent=reports.some(r=>r.type===el.dataset.done)?'제보 완료 ✓':''});if(reports.length){$('history').replaceChildren(...reports.map(r=>{const item=document.createElement('div');item.className='history-entry';const label=document.createElement('span');label.className='approved';label.textContent='승인 완료';const title=document.createElement('strong');title.textContent=challenges[r.type].title;const detail=document.createElement('div');detail.className='between';const date=document.createElement('small');date.textContent=r.date;const reward=document.createElement('span');reward.textContent='+ ₩'+money(challenges[r.type].reward);detail.append(date,reward);item.append(label,title,detail);return item;}));}}
function tab(name){for(const value of ['service','report']){$(value+'-panel').hidden=value!==name;$(value+'-tab').classList.toggle('active',value===name);$(value+'-tab').setAttribute('aria-selected',String(value===name));}}
$('service-tab').onclick=()=>tab('service');$('report-tab').onclick=()=>tab('report');
function showResult(id,text,found=false){$(id).textContent=text;$(id).classList.toggle('found',found)}
function lookup(){const id=$('note-id').value.trim();const notes={'1001':'200 OK · 소유자: 지민 (나)\n이번 주 할 일\n책 읽기, 프로젝트 아이디어 정리, 버그바운티 실습하기.','1002':'200 OK · 소유자: 지민 (나)\n떠오른 아이디어\n사람들에게 도움이 되는 작은 서비스를 만들어 보기.','1003':'200 OK · 소유자: 서연 · 비공개 메모\n다른 사용자의 메모에 접근했어요! 소유자 검증이 빠져 있습니다.\n\n'+challenges.idor.flag+'\n\n이 플래그를 복사해 취약점 제보 탭에 제출하세요.'};showResult('note-result',notes[id]||'404 Not Found · 해당 번호의 메모를 찾을 수 없습니다.',id==='1003')}
$('request-form').onsubmit=e=>{e.preventDefault();lookup()};document.querySelectorAll('[data-note]').forEach(el=>el.onclick=()=>{$('note-id').value=el.dataset.note;lookup()});
$('admin-check').onclick=()=>{const admin=$('role').value==='admin';showResult('session-result',admin?'200 OK · 관리자 페이지\n역할 값만 바꾸었는데 관리자 메뉴가 열렸어요.\n\n'+challenges.role.flag:'403 Forbidden · 일반 사용자는 관리자 메뉴에 접근할 수 없습니다.',admin)};
$('config-check').onclick=()=>showResult('session-result','200 OK · 개발 설정\nenvironment: development\ndebug: true\ninternal_flag: '+challenges.config.flag+'\n\n공개되어서는 안 되는 내부 설정이 노출되었어요.',true);
document.querySelectorAll('[data-hint]').forEach(el=>el.onclick=()=>{const hint=$('hint-'+el.dataset.hint);hint.hidden=!hint.hidden;el.textContent=hint.hidden?'힌트 보기 +':'힌트 닫기 −'});
function submitReport(type,flag,steps){if(!challenges[type])return{ok:false,message:'취약점 유형을 선택해 주세요.'};if(typeof flag!=='string'||flag.trim()!==challenges[type].flag)return{ok:false,message:'플래그와 취약점 유형이 일치하지 않아요. 발견한 값을 다시 확인해 주세요.'};if(typeof steps!=='string'||steps.trim().length<10)return{ok:false,message:'재현 과정을 공백 제외 앞뒤 정리 후 10자 이상 적어주세요.'};if(reports.some(r=>r.type===type))return{ok:false,message:'이미 보상을 받은 취약점입니다. 다른 취약점을 찾아보세요.'};reports.unshift({type,date:new Date().toLocaleDateString('ko-KR')});let saved=true;try{localStorage.setItem('bounty-lab-v1',JSON.stringify(reports))}catch{saved=false}update();return{ok:true,message:'제보 승인! 가상 계좌에 ₩'+money(challenges[type].reward)+'이 지급되었습니다. '+challenges[type].lesson+(saved?'':' 현재 브라우저에서 저장을 사용할 수 없어 새로고침 시 기록이 사라질 수 있습니다.')};}
$('report-form').onsubmit=e=>{e.preventDefault();const result=submitReport($('report-type').value,$('flag').value,$('steps').value);$('report-feedback').textContent=result.message;$('report-feedback').style.color=result.ok?'#5c7738':'#b14c43';if(result.ok){$('flag').value='';$('steps').value=''}};
$('guide-open').onclick=()=>$('guide').showModal();$('guide-close').onclick=()=>$('guide').close();$('guide-start').onclick=()=>$('guide').close();$('guide').onclick=e=>{if(e.target===$('guide')){const box=$('guide').getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)$('guide').close()}};update();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'submit_vulnerability_report',title:'취약점 제보 제출',description:'발견한 플래그와 재현 과정을 제출하고 승인된 새 제보에 가상 보상을 지급합니다.',inputSchema:{type:'object',properties:{type:{type:'string',enum:['config','idor','role']},flag:{type:'string'},steps:{type:'string',minLength:10}},required:['type','flag','steps'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const result=submitReport(input?.type,input?.flag,input?.steps);tab('report');$('report-feedback').textContent=result.message;return result;}})).catch(()=>{})}catch{}}
